-- الجهاز المُخرج من الخدمة يصير «مُكهَّناً» في سجل الأصول عند الإغلاق
create or replace function public.ops_dispose_fx() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.asset_id is not null and new.kind = 'dispose' and new.status = 'done' and old.status is distinct from 'done' then
    update public.assets set status = 'disposed', active = true, updated_at = now() where id = new.asset_id;
  end if;
  return new;
end $$;
drop trigger if exists ops_dispose_fx on public.ops_items;
create trigger ops_dispose_fx after update on public.ops_items for each row execute function public.ops_dispose_fx();

